CREATE TABLE mart.sky_summary_test (sector Nullable(Int32), n Int32, uniq Int32, total_reading Nullable(Decimal(28, 12)), mean_reading Nullable(Decimal(30, 9)), present Int32) ENGINE=MergeTree ORDER BY tuple() AS SELECT sector, count() AS n, count(DISTINCT reading) AS uniq, sumOrNull(reading) AS total_reading, CASE WHEN count("reading") = 0 THEN CAST(NULL AS Nullable(Decimal(30, 9))) ELSE CAST(round(divideDecimal(sumOrNull("reading"), toDecimal128(greatest(count("reading"), 1), 0), 33), 9) AS Nullable(Decimal(30, 9))) END AS mean_reading, count(reading) AS present FROM src_ex_observatory.readings GROUP BY sector HAVING count() > 0
;